// [ Suffix Converter ]
// Script that converts its invoked function's value from scientific notation to suffix notation, and vice-versa. Requires Suffix Button to be fully operational, otherwise defaults to scientific notation. Also includes support for an interactive calculator to convert between the two notation types.
mw.loader.getScript('https://roblox-grass-cutting-incremental.fandom.com/index.php?title=MediaWiki:SuffixConverter.js&action=raw&ctype=text/javascript');

// [ Star Chart Tree Expander ]
// Adds an interface to the Star Chart article that allows the reader to easily expand and collapse all of a given tree's table, or all of them.
mw.loader.getScript('https://roblox-grass-cutting-incremental.fandom.com/index.php?title=MediaWiki:StarChartTreeExpander.js&action=raw&ctype=text/javascript');

// [ Suffix Switcher ]
// Adds a button to easily toggle whether suffixes or scientific notation is displayed on the current article.
mw.loader.getScript('https://roblox-grass-cutting-incremental.fandom.com/index.php?title=MediaWiki:SuffixSwitcher.js&action=raw&ctype=text/javascript');

// [ Suffix Converter]
// Adds an interactive tool to easily convert an inputted value into either scientific or suffix notation types.
mw.loader.getScript('https://roblox-grass-cutting-incremental.fandom.com/index.php?title=MediaWiki:SuffixConverter.js&action=raw&ctype=text/javascript');

// [ User Page Notice ]
// Script for adding a notice to user sub-pages that the current page is not a main wiki article.
mw.loader.getScript('https://roblox-grass-cutting-incremental.fandom.com/index.php?title=MediaWiki:UserPageNotice.js&action=raw&ctype=text/javascript');

// [[ Default Upload Summary ]
